"""Draw the two small next-word graphs for the week 9 "A Simple Language Model" slides.

Styled to match docs/assets/llms/dickens-next-word-graph.svg (the instructor's
Matplotlib figure): light-blue word nodes, green for a word with no next word,
dark arrows whose width tracks the transition probability, % labels.

Both graphs share node positions so the second reads as the first plus new
transitions; the additions are drawn in amber.

    python3 sandbox/make_next_word_graphs.py
"""
from collections import Counter, defaultdict
from math import cos, sin, radians
from pathlib import Path

import matplotlib

matplotlib.use("svg")
import matplotlib.pyplot as plt
from matplotlib.patches import Circle, FancyArrowPatch

OUT = Path(__file__).resolve().parents[1] / "docs" / "assets" / "llms"

NODE_FILL, NODE_EDGE = "#aed6f1", "#1f4e79"
END_FILL, END_EDGE = "#a9dfbf", "#1e8449"
EDGE = "#2c3e50"
NEW = "#d68910"
R = 0.32  # node radius
SCALE = 1.8  # ring radius

# Words sit on a ring in reading order; "best"/"worst" split the bottom.
def ring(angle, radius=1.0):
    return (SCALE * radius * cos(radians(angle)), SCALE * radius * sin(radians(angle)))

POS = {
    "it": ring(90),
    "was": ring(30),
    "the": ring(-30),
    "best": ring(-90, 0.58),
    "worst": ring(-90, 1.3),
    "of": ring(-150),
    "times": ring(150),
}


def transitions(text):
    words = text.replace(",", "").split()
    counts = defaultdict(Counter)
    for a, b in zip(words, words[1:]):
        counts[a][b] += 1
    return {(a, b): n / sum(c.values()) for a, c in counts.items() for b, n in c.items()}


def draw(text, filename, previous=None):
    edges = transitions(text)
    words = list(dict.fromkeys(text.replace(",", "").split()))
    old_words = set(previous.replace(",", "").split()) if previous else set(words)
    old_edges = set(transitions(previous)) if previous else set(edges)
    sources = {a for a, _ in edges}

    fig, ax = plt.subplots(figsize=(7, 7))
    ax.set_xlim(-2.2, 2.2)
    ax.set_ylim(-2.75, 2.15)
    ax.set_aspect("equal")
    ax.axis("off")
    # data units -> points, so arrows stop at the node circles
    pts = lambda d: d * 72 * fig.get_figwidth() / (ax.get_xlim()[1] - ax.get_xlim()[0])

    for (a, b), p in edges.items():
        new = (a, b) not in old_edges
        rad = 0.25 if (a, b) == ("times", "it") else 0.12
        arrow = FancyArrowPatch(
            POS[a], POS[b],
            connectionstyle=f"arc3,rad={-rad}",
            arrowstyle="-|>,head_length=10,head_width=6",
            linewidth=1.5 + 3 * p,
            color=NEW if new else EDGE,
            shrinkA=pts(R) + 2, shrinkB=pts(R) + 4,
            zorder=1,
        )
        ax.add_patch(arrow)
        (x1, y1), (x2, y2) = POS[a], POS[b]
        mx, my = (x1 + x2) / 2, (y1 + y2) / 2
        # put the label on the arc, then push it sideways off the arrow, away from the ring's center
        dx, dy = x2 - x1, y2 - y1
        mx, my = mx - dy * rad / 2, my + dx * rad / 2
        length = (dx**2 + dy**2) ** 0.5
        nx, ny = dy / length, -dx / length
        if nx * mx + ny * (my + 0.3) < 0:
            nx, ny = -nx, -ny
        off = 0.22 + 0.18 * abs(nx)  # labels are wider than tall
        mx, my = mx + off * nx, my + off * ny
        ax.text(mx, my, f"{p:.0%}", ha="center", va="center", fontsize=13,
                fontweight="bold", color=NEW if new else "black",
                bbox=dict(boxstyle="round,pad=0.15", fc="white", ec="none"), zorder=3)

    for w in words:
        end = w not in sources
        new = w not in old_words
        ax.add_patch(Circle(POS[w], R, zorder=2,
                            fc=END_FILL if end else NODE_FILL,
                            ec=NEW if new else (END_EDGE if end else NODE_EDGE),
                            lw=3 if new else 1.5))
        ax.text(*POS[w], w, ha="center", va="center", fontsize=12,
                fontweight="bold", color="#1b2631", zorder=4)

    plt.rcParams["svg.fonttype"] = "path"
    fig.savefig(OUT / filename, format="svg", bbox_inches="tight", transparent=True,
                metadata={"Description": f"Next-word graph trained on: {text}"})
    plt.close(fig)


SHORT = "it was the best of times"
LONG = "it was the best of times, it was the worst of times"
draw(SHORT, "best-of-times-next-word-graph.svg")
draw(LONG, "best-worst-of-times-next-word-graph.svg", previous=SHORT)
